    wait = max(0.0, state.now - task.release)
    q_load = state.queue_len / (state.queue_len + e + 1e-6)
    aging = 1.0 + b * (1.0 + c * q_load) * wait / est
    return task.weight * tier * type_f * fit * aging / (max(est ** p, 1e-6) * max(core_penalty, 1e-6))

